#!/usr/bin/env python3
"""OpenMontage Stage B P0 component: deepfilternet3 (priority P1)."""

import base64
import hashlib
import json
import os
import shutil
import subprocess
import sys
import time
import traceback
from datetime import datetime, timezone
from pathlib import Path

os.environ.setdefault("CUDA_VISIBLE_DEVICES", "0")
os.environ.setdefault("HF_HOME", "/tmp/audit/hf")
os.environ.setdefault("XDG_CACHE_HOME", "/tmp/audit/cache")

WORK = Path("/kaggle/working/audit")
LOGS = WORK / "logs/kaggle"
RESULTS = WORK / "results"
CONFIG = WORK / "config"
ENVS = Path("/tmp/audit/envs")
REPOS = Path("/tmp/audit/repos")
WEIGHTS = Path("/tmp/audit/weights")
for _p in (WORK, LOGS, RESULTS, CONFIG, ENVS, REPOS, WEIGHTS):
    _p.mkdir(parents=True, exist_ok=True)

COMPONENT = "deepfilternet3"
PRIORITY = "P1"
KERNEL_NAME = "openmontage-p1-deepfilternet3"
REPO_URL = "https://github.com/Rikorose/DeepFilterNet"
REPO_SHA = "7b14b895fe7fc42cab72b4a4c1e49c982bd6404b"

HELPER_B64 = ""
HELPER_SHA = "1edc961ebd671ba9f628cc78f136e56ebdcbb83d3943a7d012c16e663253d56a"
FIXTURES_B64 = {"science_voice_script.txt": "", "science_terms.json": "", "image_video_prompts.json": ""}

LOG = LOGS / f"{COMPONENT}.log"
SUMMARY = RESULTS / COMPONENT
SUMMARY.mkdir(parents=True, exist_ok=True)
STATE = {"component": COMPONENT, "priority": PRIORITY, "kernel": KERNEL_NAME,
          "utc_start": None, "utc_end": None, "status": "UNKNOWN",
          "steps": {}, "errors": []}


def utc():
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def log(msg):
    line = f"{utc()} {msg}"
    print(line, flush=True)
    with LOG.open("a", encoding="utf-8") as fh:
        fh.write(line + "\n")


def sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        for chunk in iter(lambda: fh.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def sh(cmd, timeout=7200, quiet=False):
    started = time.time()
    rec = {"cmd": cmd, "returncode": None, "duration_s": None, "stdout": "", "stderr": ""}
    try:
        proc = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=timeout)
        rec["returncode"] = proc.returncode
        rec["stdout"] = proc.stdout[-20000:]
        rec["stderr"] = proc.stderr[-12000:]
    except Exception as exc:  # noqa: BLE001
        rec["error"] = f"{type(exc).__name__}: {exc}"
    rec["duration_s"] = round(time.time() - started, 3)
    if not quiet:
        log(f"$ {cmd} -> rc={rec['returncode']} {rec['duration_s']}s")
        if rec["stdout"]:
            log("stdout tail: " + rec["stdout"][-1500:].replace("\n", " | "))
        if rec["stderr"]:
            log("stderr tail: " + rec["stderr"][-1500:].replace("\n", " | "))
    return rec


def write_fixtures():
    for name, blob in FIXTURES_B64.items():
        path = CONFIG / name
        path.write_bytes(base64.b64decode(blob))
        log(f"fixture {path.name} {path.stat().st_size} bytes sha={sha256_file(path)}")


def materialise_helper():
    path = WORK / "scripts/kaggle_environment_snapshot.py"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(base64.b64decode(HELPER_B64))
    actual = sha256_file(path)
    STATE["steps"]["helper"] = {"path": str(path), "expected_sha256": HELPER_SHA,
                                 "actual_sha256": actual, "match": actual == HELPER_SHA}
    log(f"helper sha256 {actual} match={actual == HELPER_SHA}")
    if actual != HELPER_SHA:
        raise RuntimeError("helper sha mismatch")
    sys.path.insert(0, str(path.parent))
    import kaggle_environment_snapshot as snap  # noqa: PLC0415
    return snap


def ensure_env(pyver, name):
    uv = shutil.which("uv")
    if not uv:
        sh("python -m pip install --user uv", 900)
        uv = str(Path.home() / ".local/bin/uv")
    env = ENVS / name
    if not (env / "bin/python").exists():
        sh(f"{uv} venv --python {pyver} {env}", 1800)
    return env, uv


def uvpip(env, uv, args, timeout=7200):
    py = env / "bin/python"
    return sh(f"{uv} pip install --python {py} {args}", timeout)


def clone(repo_url, sha, name):
    dst = REPOS / name
    if not dst.exists():
        sh(f"git clone --recursive {repo_url} {dst}", 1800)
    sh(f"git -C {dst} checkout -q {sha}", 300)
    sh(f"git -C {dst} submodule update --init --recursive", 1800)
    return dst


def save_output(path, outputs):
    p = Path(path)
    if p.exists() and p.stat().st_size > 0:
        outputs.append({"path": str(p), "bytes": p.stat().st_size, "sha256": sha256_file(p)})
        return True
    return False


def finish(status, blocker=None, extra=None):
    STATE["utc_end"] = utc()
    STATE["status"] = status
    if blocker:
        STATE["blocker"] = blocker
    if extra:
        STATE["steps"].update(extra)
    (SUMMARY / "summary.json").write_text(json.dumps(STATE, indent=2), encoding="utf-8")
    (SUMMARY / "summary.txt").write_text(json.dumps(STATE, indent=2), encoding="utf-8")
    log("FINAL " + json.dumps({"status": status, "blocker": blocker}))
    print(json.dumps(STATE, indent=2))
    return 0 if status == "PASS" else 3


def sample_gpu(path, seconds=60):
    cmd = (f"timeout {seconds} nvidia-smi --query-gpu=timestamp,utilization.gpu,memory.used "
           f"--format=csv,noheader -l 1 > {path} 2>&1")
    return subprocess.Popen(cmd, shell=True)


def max_gpu_mib(path):
    vals = []
    for line in Path(path).read_text(errors="replace").splitlines():
        parts = [p.strip() for p in line.split(",")]
        if len(parts) >= 3 and parts[2].endswith("MiB"):
            try:
                vals.append(int(parts[2].replace("MiB", "")))
            except ValueError:
                pass
    return max(vals) if vals else None


def run():
    snap = materialise_helper(); write_fixtures(); STATE["utc_start"] = utc()
    b = snap.collect(LOGS, "before_dfn"); t4 = snap.assert_t4(b)
    if not t4["ok"]: return finish("BLOCKED", "T4 assertion failed")
    env, uv = ensure_env("3.11", "deepfilternet")
    uvpip(env, uv, "torch==2.6.0 torchaudio==2.6.0 --index-url https://download.pytorch.org/whl/cu126", 7200)
    inst = uvpip(env, uv, "deepfilternet numpy soundfile", 3600)
    if inst["returncode"] != 0:
        return finish("BLOCKED", "deepfilternet install failed", {"install": inst["stderr"][-2000:]})
    repo = clone(REPO_URL, REPO_SHA, "deepfilternet")  # pinned source, provenance only
    outdir = RESULTS / "deepfilternet3"; outdir.mkdir(parents=True, exist_ok=True)
    prep = """
import numpy as np, soundfile as sf
sr=48000; dur=30.0; t=np.arange(int(sr*dur))/sr
rng=np.random.default_rng(1234)
clean=0.1*np.sin(2*np.pi*440*t)+0.05*np.sin(2*np.pi*220*t)
noise=0.05*rng.standard_normal(clean.shape)
noisy=clean+noise
sf.write(__CLEAN__, clean.astype(np.float32), sr, subtype='PCM_16')
sf.write(__NOISY__, noisy.astype(np.float32), sr, subtype='PCM_16')
print('prep ok')
""".replace("__CLEAN__", repr(str(outdir/"clean.wav"))).replace("__NOISY__", repr(str(outdir/"noisy.wav")))
    (WORK/"scripts/dfn_prep.py").write_text(prep, encoding="utf-8")
    prep_run = sh(f"{env}/bin/python {WORK/'scripts/dfn_prep.py'}", 600)
    if prep_run["returncode"] != 0:
        return finish("BLOCKED", "dfn test signal generation failed")
    # official CLI usage (README): deepFilter path/to/noisy_audio.wav --output-dir <dir>
    cmd = f"{env}/bin/deepFilter --output-dir {outdir} {outdir/'noisy.wav'}"
    gpup = subprocess.Popen(f"timeout 3600 nvidia-smi --query-gpu=timestamp,utilization.gpu,memory.used --format=csv,noheader -l 1 > {WORK}/dfn_gpu.txt", shell=True)
    t0 = time.time(); run = sh(cmd, 3600); elapsed = time.time() - t0
    gpup.terminate()
    produced = [p for p in sorted(outdir.glob("*.wav")) if p.name not in ("noisy.wav", "clean.wav")]
    m = {"gen_s": round(elapsed, 3), "in_s": 30.0, "peak_vram_mib": max_gpu_mib(WORK / "dfn_gpu.txt")}
    if produced:
        chk = """
import json, sys, soundfile as sf
i = sf.info(sys.argv[1])
print(json.dumps({'path': sys.argv[1], 'sr': i.samplerate, 'frames': i.frames,
                  'seconds': i.frames / i.samplerate, 'subtype': i.subtype, 'channels': i.channels}))
"""
        (WORK/"scripts/dfn_check.py").write_text(chk, encoding="utf-8")
        r = sh(f"{env}/bin/python {WORK/'scripts/dfn_check.py'} {produced[0]}", 300)
        for line in r["stdout"].splitlines():
            if line.strip().startswith("{"):
                try: m.update(json.loads(line))
                except Exception: pass
    if m.get("seconds"):
        m["drift_ms"] = abs(m["seconds"] - 30.0) * 1000.0
        m["rtf"] = m["gen_s"] / 30.0
    outs = []
    for p in [outdir/"clean.wav", outdir/"noisy.wav"] + produced: save_output(p, outs)
    STATE["steps"].update({"inference": {"rc": run["returncode"], "stderr": run["stderr"][-3000:]}, "metrics": m, "outputs": outs})
    ok = run["returncode"] == 0 and bool(produced) and m.get("drift_ms") is not None and m["drift_ms"] < 500
    return finish("PASS" if ok else "FAIL", None if ok else "dfn run failed",
                  {"dtype": "FP32", "runtime_seconds": m.get("gen_s"), "drift_ms": m.get("drift_ms"),
                   "peak_vram_mib": m.get("peak_vram_mib"), "subtype": m.get("subtype")})


if __name__ == '__main__':
    try:
        raise SystemExit(run())
    except SystemExit:
        raise
    except Exception:
        tb = traceback.format_exc(); print(tb); log('UNHANDLED ' + tb[-3000:]); finish('FAIL', 'unhandled exception'); raise SystemExit(4)
